/*
 * A228200  Smallest of 9 consecutive primes whose sum is not a prime.
 * https://oeis.org/A228200
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the smallest prime in the first block of 9 consecutive
 *            primes whose sum is composite. The sequence is generated by
 *            testing 9‑prime blocks in order of appearance. It is implemented
 *            with a sliding window and a cache of the computed terms
 * Range:     u8 n <= 5, u16 n <= 540, u32 n <= 760, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <stddef.h>

#include "../utils/is_prime.h"      /* bool is_prime(idx_t x);   */
#include "../utils/is_prime_big.h"  /* bool is_prime_big(seq_t n); */

static void grow_seq(seq_t **arr, size_t *cap, size_t needed)
{
    if (*cap < needed) {
        size_t new_cap = (*cap == 0) ? 16 : (*cap << 1);
        if (new_cap < needed) new_cap = needed;
        seq_t *tmp = (seq_t *)realloc(*arr, new_cap * sizeof(seq_t));
        if (!tmp) abort();                 /* out of memory */
        *arr = tmp;
        *cap = new_cap;
    }
}

/* Return the n-th term of OEIS A228200 (1‑based index). */
seq_t a(idx_t n)
{
    /* Cache of already computed terms (1‑based indexing). */
    static seq_t *term_cache = NULL;
    static size_t term_len = 0;   /* number of terms stored so far */
    static size_t term_cap = 0;   /* capacity of term_cache            */

    /* State for generating primes and maintaining the 9‑prime sliding window. */
    static idx_t cur_candidate = 2;   /* next integer to test for primality    */
    static idx_t win[9] = {0};        /* sliding window of the last 9 primes   */
    static idx_t win_idx = 0;         /* index where next prime will be stored */
    static size_t win_cnt = 0;        /* how many primes are currently in the window */
    static seq_t win_sum = 0;         /* sum of the primes in the current window */

    /* Generate terms until the cache contains at least n terms. */
    while (term_len < n) {
        /* Find the next prime.  cur_candidate is always odd after 2. */
        idx_t p;
        if (cur_candidate == 2) {
            p = 2;
            cur_candidate = 3;
        } else {
            while (!is_prime(cur_candidate))
                cur_candidate += 2;
            p = cur_candidate;
            cur_candidate += 2;
        }

        /* Add the new prime to the sliding window and update the sum. */
        if (win_cnt < 9) {
            /* Window not yet full. */
            win[win_idx] = p;
            win_sum += (seq_t)p;
            win_idx = (win_idx + 1) % 9;
            ++win_cnt;

            if (win_cnt == 9) {
                /* Window just became full; test the sum. */
                if (!is_prime_big(win_sum)) {
                    grow_seq(&term_cache, &term_cap, term_len + 1);
                    /* The smallest prime in the current 9‑prime block
                       is the one that was most recently overwritten,
                       which now resides at win[win_idx] (after the increment). */
                    term_cache[term_len++] = (seq_t)win[win_idx];
                }
            }
        } else {
            /* Window already full: discard oldest, add new. */
            idx_t old = win[win_idx];
            win_sum = win_sum - (seq_t)old + (seq_t)p;
            win[win_idx] = p;
            win_idx = (win_idx + 1) % 9;

            /* After the update, win[win_idx] holds the smallest prime
               of the current 9‑prime window. */
            if (!is_prime_big(win_sum)) {
                grow_seq(&term_cache, &term_cap, term_len + 1);
                term_cache[term_len++] = (seq_t)win[win_idx];
            }
        }
    }

    /* idx_t is unsigned, but the cache index is small enough to cast safely. */
    return term_cache[(size_t)(n - 1U)];
}
